local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[404702]=b({e[17034],404702,1,4,258,"「いいえ、まだ眠くありません。ただ、目が痒いだけです。\n本当です、もうちょっと遊べますよ。\nだから、僕を置いていかないでくださいね？ お姉さま……。」",200047,1,"deco/character/404702",302002,60,false,false,false,false,false,"0",1775,869,399,939,728,2045,2093,939,728,2045,1101,false,false,false,false,false,false,false,false,false,false,false,false,false,false,0},h)g[404703]=b({e[17034],404703,4,109,259,"「しーっ。今はマジックタイムです、お静かに。一番好きなものを思い浮かべて下さい。…心の声、聞こえましたよ……箱を開けてみて下さい。……中身は僕でした～！　やっぱり、お姉さまが一番好きなのは僕だったんですね！」",200047,2,"deco/character/404703",false,false,1,false,false,false,false,"0",2021,980,398,1128,236,1677,2614,1128,678,1677,1261,false,false,false,false,false,false,false,false,false,false,false,false,false,false,0},h)g[404704]=b({e[21034],404704,3,24,260,"「ハロウィンのりんごは、色鮮やかなものほど毒があるって言われてるんです。お姉さまがくださるものなら、いただきますけど……あぁ、どんな風に起こしてもらえるんでしょう、ドキドキしちゃいます。」",200047,2,"deco/character/404704",false,false,false,false,false,false,false,"0",false,"100,0,1",false,"100,-120,1",1894,891,396,814,699,2545,2369,814,699,2545,1150,1,3769,4173,2104,3618,8000,8500,16000,9667,13000,false,8000,false,false,0},h)g[404705]=b({e[17045],404705,2,74,261,"「お姉さま、まだ撮ってますか？ よかった、どうかそのままで。\nこの身に傷を負おうとも、必死にお姉さまの視界にいようとする僕の姿を、どうしても見てほしくて……\nこの動画をお姉さまが見返すたび、お姉さまの心が僕一人だけのものになっていくはず……そうですよね？」",200047,2,"deco/character/404705",false,false,false,false,false,false,false,"0",1,3769,4173,2104,3618,8000,8500,16000,9667,13000,false,8000,"laien_xr",false,0},h)g[404801]=b({e[46057],404801,false,124,262,false,200048,false,"deco/character/senchuanlingzi",302002,60,1,false,false,false,34,false,false,false,false,false,false,false,false,"120,-70,1.02",false,"-30,50,1",false,false,false,"0,40,1","0,40,1",false,false,false,1844,947,393,953,734,2014,2479,953,734,2014,1170,"senchuanlingzi"},h)g[404802]=b({e[17034],404802,1,4,263,"「こ、これが、君が好きな、お日さまの日差しなの？\nもっと日差しを浴びたら、私も君みたいに、お友達がたくさん出来るかな……。\n頑張ってみるから、明日も、一緒にひなたぼっこしたいの。」",200048,1,"deco/character/senchuanlingzi_0",302002,60,1,false,false,false,false,"0",1839,913,399,766,644,2468,2556,766,644,2468,1229,false,false,false,false,false,false,false,false,false,false,false,false,"senchuanlingzi_0"},h)g[404803]=b({e[21034],404803,9,87,264,"「こ、これは……いい夢を見せるための魔法陣なの。お泊りに来てもらった友達は君が初めてだから、その…いい夢を見てもらいたいな……って……」",200048,2,"deco/character/404803",false,false,false,false,false,false,false,false,false,false,false,"0,-140,1",1953,950,380,1005,562,2128,1997,1005,639,2128,1261,1,3475,5000,1801,3207,8000,13333,6333,3166,10000,false,8000,"senchuanlingzi_sy",false,0},h)g[404804]=b({e[17034],404804,12,49,265,"「私と一緒に踊りたい、の……？　嬉しいけど、踊るってことは、両手が君の体に触れることになっちゃうの。君に不幸が移るのが怖いの……。君はずっと、この世で一番幸運な人でいて欲しいの。」",200048,2,"deco/character/senchuanlingzi_LF",false,false,1,false,false,false,false,"0",1924,873,388,836,688,2472,2707,836,688,2472,1139,false,false,false,false,false,false,false,false,false,false,false,false,"senchuanlingzi_lf"},h)g[404805]=b({e[24034],404805,3,55,266,"「あの、私の役は『幽霊の花嫁』で……。それで、もし良かったら、台詞の練習に付き合って欲しいの。　じ、じゃあ、始めるの……『ヒ、ヒッヒッヒ、ここまで来たからには、私の魂の、は、半身として残ってもらいます！』」",200048,2,"deco/character/senchuanlingzi_WS",false,false,false,false,false,false,false,false,false,false,"-150,0,1","240,-140,1","-150,0,1","-280,0,1","-150,0,1",2081,842,393,596,473,2868,2869,596,538,2868,1261,1,5437,5000,3086,2651,8000,15666,14166,12666,15000,8000,8000,"senchuanlingzi_ws"},h)g[404806]=b({e[17045],404806,4,99,267,"「雪、なの……。\nごめんなさい……こんな日に呼び出して。髪に雪が積もってるし、手もきっと、冷たくなってるの。\nじ、実は今日、花子が、「鹿の角をつけて、大切な人と会えば、その人は鹿の角を持つ精霊の加護を受けられる」って言ったの……\nそ、それで……私、わがままなの……？」",200048,2,"deco/character/senchuanlingzi_sd",false,false,false,false,false,false,false,"",1,1959,5000,986,2117,5333,10233,12699,8366,10000,8000,5333,"senchuanlingzi_sd"},h)g[404901]=b({e[33057],404901,false,125,268,false,200049,false,"deco/character/longchuanxiayan",302002,60,false,false,false,false,-85,"0.949999988",false,false,false,false,false,false,false,"0,470,0.94","-60,30,0.95","0,30,0.95","0,0,0